//! JSON API of the `products` resource, generated by
//! `forge generate resource` (and `forge generate scaffold`). Handlers stay
//! thin: authorize, decode the request, call [`ProductService`], answer
//! JSON.
//!
//! | Method | Path | Action | Permission |
//! | --- | --- | --- | --- |
//! | `GET` | `/v1/products?cursor=ID` | list, in creation order, `PAGE_SIZE` per page | `products:read` |
//! | `POST` | `/v1/products` | create: `201` with `Location` | `products:write` |
//! | `GET` | `/v1/products/{id}` | show | `products:read` |
//! | `PATCH` | `/v1/products/{id}` | change the members sent, with the `version` read | `products:write` |
//! | `DELETE` | `/v1/products/{id}?version=N` | delete the version read: `204` | `products:write` |
//!
//! Products belong to a tenant: the tenant is the one the bearer token was
//! issued for (`crate::adapters::http::api_access`), never a path, query or
//! header value, and every statement binds it.
//!
//! A stale `version` answers `409`, an invalid value `422` with a message
//! per member in `metadata`, an unknown `{id}` `404`. `PATCH` changes only
//! the members it names; `null` clears an optional one. Every route is
//! described in the OpenAPI document (`GET /openapi.json`, `forge openapi`).

use std::future::Future;
use std::sync::Arc;

use forge::ComposeError;
use forge::core::{ErrorCategory, ForgeError, Version};
use forge::http::{HeaderValue, Method, Request, Response, Router, StatusCode, header};
use forge::openapi::{OpenApiSchema, Operation, Param, describe};
use forge::security::Permission;
use forge::tenancy::BearerDenied;
use forge::web::Patch;
use serde::{Deserialize, Serialize};

use crate::adapters::http::api_access::ApiTenantAccess;
use crate::application::use_cases::products::{
    ProductError, ProductService, READ_PERMISSION, WRITE_PERMISSION,
};
use crate::domain::entities::product::{Product, ProductAttributes, ProductId};

/// The collection's path.
pub const COLLECTION_PATH: &str = "/v1/products";

/// A product as the API answers it.
#[derive(Debug, Serialize, OpenApiSchema)]
pub struct ProductJson {
    /// The product's UUIDv7.
    pub id: ProductId,
    pub name: String,
    pub summary: Option<String>,
    pub price_cents: i64,
    /// The optimistic-locking version: `PATCH` and `DELETE` send it back.
    pub version: i64,
}

impl From<&Product> for ProductJson {
    fn from(product: &Product) -> Self {
        let ProductAttributes {
            name,
            summary,
            price_cents,
        } = product.attributes().clone();
        Self {
            id: product.id(),
            name,
            summary,
            price_cents,
            version: product.version().get(),
        }
    }
}

/// One page of products.
#[derive(Debug, Serialize, OpenApiSchema)]
pub struct ProductList {
    pub items: Vec<ProductJson>,
    /// The `cursor` of the next page; `null` on the last one.
    pub next_cursor: Option<ProductId>,
}

/// The body of `POST`: every required member.
#[derive(Debug, Deserialize, OpenApiSchema)]
pub struct NewProduct {
    pub name: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub summary: Option<String>,
    pub price_cents: i64,
}

impl From<NewProduct> for ProductAttributes {
    fn from(body: NewProduct) -> Self {
        let NewProduct {
            name,
            summary,
            price_cents,
        } = body;
        Self {
            name,
            summary,
            price_cents,
        }
    }
}

/// The body of `PATCH`: the version read and the members to change. A member
/// left out stays as it is; `null` clears an optional one.
#[derive(Debug, Deserialize, OpenApiSchema)]
pub struct ProductChanges {
    /// The version the client last read.
    pub version: i64,
    #[serde(default, skip_serializing_if = "Patch::is_absent")]
    pub name: Patch<String>,
    #[serde(default, skip_serializing_if = "Patch::is_absent")]
    pub summary: Patch<String>,
    #[serde(default, skip_serializing_if = "Patch::is_absent")]
    pub price_cents: Patch<i64>,
}

impl ProductChanges {
    /// Applies the members sent to `attributes`; `null` for a required
    /// member is refused.
    fn apply(self, attributes: &mut ProductAttributes) -> Result<(), ForgeError> {
        match self.name {
            Patch::Absent => {}
            Patch::Null => return Err(not_null("name")),
            Patch::Value(value) => attributes.name = value,
        }
        match self.summary {
            Patch::Absent => {}
            Patch::Null => attributes.summary = None,
            Patch::Value(value) => attributes.summary = Some(value),
        }
        match self.price_cents {
            Patch::Absent => {}
            Patch::Null => return Err(not_null("price_cents")),
            Patch::Value(value) => attributes.price_cents = value,
        }
        Ok(())
    }
}

/// The query of `GET /v1/products`.
#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct ListQuery {
    cursor: Option<ProductId>,
}

/// The query of `DELETE`: the version the client last read.
#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct DeleteQuery {
    version: i64,
}

/// What every handler shares.
struct ProductApi {
    service: ProductService,
    access: Arc<dyn ApiTenantAccess>,
    read: Permission,
    write: Permission,
}

/// Registers the routes. `access` decides who may call them (see
/// `crate::adapters::http::api_access`); nothing is served before it agrees.
pub fn routes(
    router: &mut Router,
    service: ProductService,
    access: Arc<dyn ApiTenantAccess>,
) -> Result<(), ComposeError> {
    let state = Arc::new(ProductApi {
        service,
        access,
        read: Permission::new(READ_PERMISSION).map_err(ComposeError::other)?,
        write: Permission::new(WRITE_PERMISSION).map_err(ComposeError::other)?,
    });
    let member = format!("{COLLECTION_PATH}/{{id}}");
    let id = || Param::path::<ProductId>("id").doc("The product's ID.");
    route(
        router,
        &state,
        Method::GET,
        COLLECTION_PATH,
        list,
        operation(
            "listProducts",
            "List products, in creation order",
            READ_PERMISSION,
        )
        .param(
            Param::query::<Option<ProductId>>("cursor")
                .doc("The next_cursor of the previous page."),
        )
        .json::<ProductList>(200)
        .errors([422]),
    )?;
    route(
        router,
        &state,
        Method::POST,
        COLLECTION_PATH,
        create,
        operation("createProduct", "Create a product", WRITE_PERMISSION)
            .request::<NewProduct>()
            .response(forge::openapi::Response::json::<ProductJson>(201).header("Location")),
    )?;
    route(
        router,
        &state,
        Method::GET,
        &member,
        show,
        operation("getProduct", "Get a product", READ_PERMISSION)
            .param(id())
            .json::<ProductJson>(200)
            .errors([400, 404]),
    )?;
    route(
        router,
        &state,
        Method::PATCH,
        &member,
        update,
        operation(
            "updateProduct",
            "Change some members of a product",
            WRITE_PERMISSION,
        )
        .param(id())
        .request::<ProductChanges>()
        .json::<ProductJson>(200)
        .errors([400, 404, 409]),
    )?;
    route(
        router,
        &state,
        Method::DELETE,
        &member,
        destroy,
        operation("deleteProduct", "Delete a product", WRITE_PERMISSION)
            .param(id())
            .param(
                Param::query::<i64>("version")
                    .required()
                    .doc("The version the client last read."),
            )
            .response(forge::openapi::Response::empty(204))
            .errors([400, 404, 409, 422]),
    )?;
    Ok(())
}

/// The description every route shares: bearer authentication, the
/// permission and the access policy's `503`.
fn operation(id: &str, summary: &str, permission: &str) -> Operation {
    Operation::new()
        .id(id)
        .summary(summary)
        .tag("products")
        .bearer()
        .permission(permission)
        .errors([503])
}

fn route<H, F>(
    router: &mut Router,
    state: &Arc<ProductApi>,
    method: Method,
    path: &str,
    handler: H,
    operation: Operation,
) -> Result<(), ComposeError>
where
    H: Fn(Arc<ProductApi>, Request) -> F + Send + Sync + 'static,
    F: Future<Output = Response> + Send + 'static,
{
    let state = Arc::clone(state);
    router.route(
        method,
        path,
        describe(
            move |request: Request| handler(Arc::clone(&state), request),
            operation,
        ),
    )?;
    Ok(())
}

async fn list(state: Arc<ProductApi>, request: Request) -> Response {
    let context = match state.access.authorize(&request, &state.read).await {
        Ok(context) => context,
        Err(denied) => return forge::web::bearer_refusal(denied),
    };
    let query: ListQuery = match forge::web::decode_query(&request) {
        Ok(query) => query,
        Err(failure) => return forge::web::error(&failure),
    };
    match state.service.list(&context, query.cursor).await {
        Ok(page) => forge::web::json(
            StatusCode::OK,
            &ProductList {
                items: page.products.iter().map(ProductJson::from).collect(),
                next_cursor: page.next,
            },
        ),
        Err(error) => failure(error),
    }
}

async fn create(state: Arc<ProductApi>, request: Request) -> Response {
    let context = match state.access.authorize(&request, &state.write).await {
        Ok(context) => context,
        Err(denied) => return forge::web::bearer_refusal(denied),
    };
    let body: NewProduct = match forge::web::decode_json_strict(&request) {
        Ok(body) => body,
        Err(failure) => return forge::web::error(&failure),
    };
    match state.service.create(&context, body.into()).await {
        Ok(product) => {
            let mut response = forge::web::json(StatusCode::CREATED, &ProductJson::from(&product));
            if let Ok(location) =
                HeaderValue::from_str(&format!("{COLLECTION_PATH}/{}", product.id()))
            {
                response.headers_mut().insert(header::LOCATION, location);
            }
            response
        }
        Err(error) => failure(error),
    }
}

async fn show(state: Arc<ProductApi>, request: Request) -> Response {
    let context = match state.access.authorize(&request, &state.read).await {
        Ok(context) => context,
        Err(denied) => return forge::web::bearer_refusal(denied),
    };
    let Some(id) = path_id(&request) else {
        return invalid_id();
    };
    match state.service.find(&context, id).await {
        Ok(product) => forge::web::json(StatusCode::OK, &ProductJson::from(&product)),
        Err(error) => failure(error),
    }
}

async fn update(state: Arc<ProductApi>, request: Request) -> Response {
    let context = match state.access.authorize(&request, &state.write).await {
        Ok(context) => context,
        Err(denied) => return forge::web::bearer_refusal(denied),
    };
    let Some(id) = path_id(&request) else {
        return invalid_id();
    };
    let changes: ProductChanges = match forge::web::decode_json_strict(&request) {
        Ok(changes) => changes,
        Err(failure) => return forge::web::error(&failure),
    };
    let expected = match Version::new(changes.version) {
        Ok(expected) => expected,
        Err(failure) => return forge::web::error(&failure),
    };
    // The stored attributes with the members sent; the update itself checks
    // that the version read is still the stored one.
    let mut attributes = match state.service.find(&context, id).await {
        Ok(product) => product.attributes().clone(),
        Err(error) => return failure(error),
    };
    if let Err(failure) = changes.apply(&mut attributes) {
        return forge::web::error(&failure);
    }
    match state
        .service
        .update(&context, id, expected, attributes)
        .await
    {
        Ok(product) => forge::web::json(StatusCode::OK, &ProductJson::from(&product)),
        Err(error) => failure(error),
    }
}

async fn destroy(state: Arc<ProductApi>, request: Request) -> Response {
    let context = match state.access.authorize(&request, &state.write).await {
        Ok(context) => context,
        Err(denied) => return forge::web::bearer_refusal(denied),
    };
    let Some(id) = path_id(&request) else {
        return invalid_id();
    };
    let expected = match forge::web::decode_query::<DeleteQuery>(&request)
        .and_then(|query| Version::new(query.version))
    {
        Ok(expected) => expected,
        Err(failure) => return forge::web::error(&failure),
    };
    match state.service.delete(&context, id, expected).await {
        Ok(()) => Response::empty(StatusCode::NO_CONTENT),
        Err(error) => failure(error),
    }
}

/// The route's `{id}`, when it is a UUIDv7.
fn path_id(request: &Request) -> Option<ProductId> {
    request.path_param_as("id").ok()
}

/// `400 invalid_id`: the `{id}` is not a UUIDv7.
fn invalid_id() -> Response {
    let failure = ForgeError::new(
        ErrorCategory::Validation,
        "invalid_id",
        "the product ID is not a UUIDv7",
    );
    forge::web::json(StatusCode::BAD_REQUEST, &failure.report())
}

/// The JSON answer to a failed use case.
fn failure(error: ProductError) -> Response {
    match error {
        ProductError::Invalid(violations) => {
            let mut failure = ForgeError::new(
                ErrorCategory::Validation,
                "validation_failed",
                "the product is invalid",
            );
            for (field, violation) in violations.iter() {
                failure = failure.with_metadata(field.name(), violation.to_string());
            }
            forge::web::error(&failure)
        }
        ProductError::NotFound => forge::web::error(&ForgeError::new(
            ErrorCategory::NotFound,
            "product_not_found",
            "product not found",
        )),
        ProductError::Conflict => forge::web::error(&ForgeError::new(
            ErrorCategory::Conflict,
            "product_conflict",
            "the product was changed by someone else",
        )),
        ProductError::Forbidden => forge::web::bearer_refusal(BearerDenied::Forbidden),
        // Logged with its cause chain; the client sees a generic report.
        ProductError::Store(error) => forge::web::error(
            &ForgeError::new(
                ErrorCategory::Infrastructure,
                "product_storage_failed",
                "service temporarily unavailable",
            )
            .with_source(error),
        ),
    }
}

/// `null` for a member that cannot be empty.
fn not_null(member: &str) -> ForgeError {
    ForgeError::new(
        ErrorCategory::Validation,
        "validation_failed",
        "the product is invalid",
    )
    .with_metadata(member, "can't be null")
}
